) AS (
  VALUES 
    (617::BIGINT, 'Aprenda a modelar SOLO y no se le ocurra preguntarle algo pq: "deberían ya de saberlo todo". Trate de no llevárselo entre ojos pq le gusta guardar rencor. La clase depende de su estado de ánimo. Vaya a consulta e ignore cuando lo trata "mal" tomeselo como "juego"'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, '5ad74d6edcb51348616cbebb33652e7689f8e5710ffd9f0dea1514c152c573c7'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Machista, nota más alta a mujeres y el grupo le puede caer bien o mal de manera aleatoria, responde mensajes de manera irrespetuosa, y espera trabajos perfectos sin brindar apoyo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-10-14T00:00:00+00:00'::TIMESTAMPTZ, 'a01bfe3d0e5338831165783e49ecc8476a26d16a23fbf5bc27ff66695fcba3d9'::TEXT, ARRAY[1851, 1853]::BIGINT[]),
    (617::BIGINT, 'El profesor sabe mucho y se aprende si se tiene ganas de prestar atención, esto no quita que él no suele responder a consultas porque "Usted ya debería saber esto", es desordenado a la hora de evaluar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2025-09-06T00:00:00+00:00'::TIMESTAMPTZ, '6d97014c43112851f4e478ba0fbccc8151d9e81f4b734432660c71e2b958208f'::TEXT, ARRAY[1851, 1853]::BIGINT[]),
    (617::BIGINT, 'Buen profesor, lo único malo es que no tiene un cronograma para irse guiando. Es mejor dando modelado que tridi, las tareas son algo largas pero da buen tiempo para hacerlas. Califica normal.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'feee46cf5fdb8878501f28d1967211c716653063ef23aab1ad9321b114cf3dc8'::TEXT, ARRAY[1853]::BIGINT[]),
    (617::BIGINT, 'El profe es super buena gente y muy comprensivo en cuanto a los tiempos de entregas de trabajo; sin embargo, no tiene una lista clara de lo que va a evaluar durante en el semestre y al final termina dando las notas hasta el final y uno no puede saber como va hasta que termine el semestre.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'cb7ddb62c32050662e67ed19c5c6c2900bbc2167faf08d4d1b6d2a7e2a2dc0f2'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Fede es un profe que tiene muchísimo por enseñar y contar, tiene mucha experiencia como Diseñador y sabe demasiado; quizá el problema lo tiene él al comunicarlo. Si usted se interesa en la clase y le pregunta cosas, fijo aprende muchísimo más de lo que espera.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd28ca4f96312add752bef1d553be72114e8323f858167202bf8a18538eb1b1e7'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Al inicio puede ser abrumador pero el profe es muy bueno explicando, eso si, explica todo muy rápido. El problema: es desorganizado con los trabajos, no se sabe claramente cuándo o qué va a evaluar y no dio las notas hasta el final del semestre (evaluó suave pero uno se la pasa con incertidumbre)'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'f8f29779a49c15db130c5eb91a32dc9b61540db004e79dcb2e45d86edb296ab9'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Deja muchos trabajos que al final no evalúa, suele dar tiempo para las entregas pero así es que se termina en semana 18 o 19. Las calificaciones son un poco al azar, ya que depende del humor que tenga en el momento. Durante las clases solo se hacer practica y explica los proyectos'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1e713116945ecc455e1dfad8404159a0f745720e4e8ea819b7a59d18eb5c9348'::TEXT, ARRAY[1853]::BIGINT[]),
    (617::BIGINT, 'Fede es un amor, es un excelente profe, entiende la carga académica que tenemos por lo que si es necesario alargar la entrega de un trabajo, lo hace; las instrucciones de los ejercicios son super claras y en las consultas da muy buena retroalimentación. Super recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-01-06T00:00:00+00:00'::TIMESTAMPTZ, '8cee04ce15ff58388e691ccde9f6bb7fa540955eff6c8792091db1ee7902df41'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'No hay muchas clases sincronicas ya que deja ese tiempo para los trabajos. Es comprensible y ayuda mucho a los estudiantes con las dudas y con el tiempo. Explica bien la materia y se entiende perfectamente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '02f20c429393d8e02398f67e4cdd5d125dfb8044c550bc047e37d54536f43170'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Uno de los mejores profesores, apesar de dar clase como cada 15 días y solo para explicar los trabajos, es super comprensivo y ayuda bastante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '97890abdcfdc15ee01636c3a35a83c02091193a736d9345cf367c679c4a14344'::TEXT, ARRAY[1853]::BIGINT[]),
    (617::BIGINT, 'La clase es completamente asincrónica, por lo que hay que leer bastante y organizarse bien para ir al día. Deja los trabajos con tiempo y con instrucciones claras. Brinda apoyo si uno se lo pide.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'eb1f489d4ae504ff94087283e1420b68b97b5c4bb62aba2ad89dcb86e352e136'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'El curso en la virtualidad fue un poco confuso, pero con los trabajos que se realizaron gran parte de los contenidos quedan claros. El profe ayuda y le importa que los estudiantes pasen y entiendan. Asincrónico.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '6e5191f87f110abb4b818c554e8aa2690a1e274612f3b8c0f3320c017aabd45d'::TEXT, ARRAY[1853]::BIGINT[]),
    (617::BIGINT, 'Federico en virtual es un 10/10, se interesa de que uno aprenda. Deja lecciones clases, da mucha ayuda y uno sí aprende y hace trabajos demasiado chivas que hacen que uno quiera hacer más con la clase. Es super claro y comprensivo con los estudiantes. Si puede matricular virtual con el HAGALO'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '8d5cc69bfaad9044f987389fb80c9af1b5d0865626325ea8f466e567e59dc65a'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'El profe Fede es demasiado genial, sabe muchísimo. Modelado es un curso que lleva tiempo así que tome en cuenta eso y trate de cada semana pedir consulta, el profe va a resolver todas sus dudas muy amablemente, se nota que le gusta enseñar, lo único es que si tarda un poco con las notas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '1e3b42ffee54fdc19c55f13b5593f30ee4ecd04f12098379ef8cd686d6a74104'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Este profe es genial. Demasiado profesional y es un experto en su área. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec4ac161964c336613a65ba770830f66412b64e0bbe877b398b8da3cebcb438f'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Federico es un crack en el área de modelado 3d y una excelente persona, sin embargo no está preparado para dar Principios Estructurales, no aprendimos nada y terminó regalando la nota. Si desea aprender algo lea el libro que recomienda al inicio de lecciones o matricule con otro profesor.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'fc949b0fc8334062b66a6eea235e603491b90e0e26f493f4cc4a8a7276703e56'::TEXT, ARRAY[1854]::BIGINT[]),
    (617::BIGINT, 'Es un excelente profesor! Si uno muestra interés en la materia el curso está casi aprobado! En serio súper recomendado. El profe además se nota que ama lo que hace y contagia esas ganas de trabajar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'a3eb61c9b98ff93295295efb5f26155d417ba9175b022fa4059bee5b3cdb5216'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-13T00:00:00+00:00'::TIMESTAMPTZ, '520fd69a9176939c1fcbe6df327a4c95c57c12985bf321de6f71430917cdb624'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'El profe sabe demasiado, el curso si es duro, hay que ponerle pero con el se aprende mucho. En poco tiempo uno hace cosas muy chivas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-12-30T00:00:00+00:00'::TIMESTAMPTZ, '49965c45f09e3bc925c61388ca8bf5dfc77bf7a5ed4c7005b165d90ff9e9ce85'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Sabe demasiado, es increíble ver como tiene solución a cada problema que se presenta. Califica justamente y hay que practicar bastante para los quices. ¡Matricule sin miedo!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5a6490ef889a330674ebad3e91d900dbf50764c6a5494cf0d87944c94105f461'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Él sabe un MONTÓN, es el mejor, se aprende mucho con él de todo no solo sobre el curso sino de la vida, en modelado el es un crack y por lo mismo es un poco dificil seguirle el hilo pero si se pasa, recomendadísimo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8ee3ccab1b0aa5314a16eebf6662d50cf9728cde0bd5865bf7d42c0afa3c0a4c'::TEXT, ARRAY[1927, 1931, 1851]::BIGINT[]),
    (617::BIGINT, 'Mas o menos estricto, muy responsable y respetuoso pero realmente enseña muy bien y ayuda a quien el ve que se esfuerza.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a4295e4ab010fd9fe33c8ea981c2ab0277af449c6e7738d36e1d4043baf738d9'::TEXT, ARRAY[1927, 1931, 1936]::BIGINT[]),
    (617::BIGINT, 'El profe es algo disperso y aveces como que se le olvida que estaba haciendo es un poco vacilon pero si uno le pregunta siempre te va ayudar, y se preocupa mucho por el estudiantes es muy comprensivo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9a37e58836f2b91c36f3f3a06da956a49d14c58ac353ed9f37ce02c1126ce99'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Es un amor de persona, es estricto, pero solo lo necesario. Va a aprender TONELADAS con él, no dude en matricular con él.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '61c1a5b65ff161c6693664977904d6f30ae7e3d752b92892a99e99f68e2d5cb3'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'bc06db3a426ccec9f1a194799731ec56de156bb287769b21a839c5b930cf611f'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-12-12T00:00:00+00:00'::TIMESTAMPTZ, '52d89cc564fd464fb17ecf4d6eba5a64967f7489b87a5626e3d6c89c4adbb3fe'::TEXT, ARRAY[1851]::BIGINT[]),
    (617::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-07-28T00:00:00+00:00'::TIMESTAMPTZ, '66a72a6cfd9037da8bc741efbaeeea8a3a6bbf107a7f805b90dc824f5e8d3051'::TEXT, ARRAY[1931]::BIGINT[]),
    (617::BIGINT, 'Este profe es una teja'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, '7d8024e4ad7e32088903f85d0935f8125783ac1b63fd2aacc87d09ab2fed0c53'::TEXT, ARRAY[1854]::BIGINT[]),
    (617::BIGINT, 'Excelente curso el de Modelado'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'c768ac94f4c0474f702c54bf5440d4af9e74243058014c40a678d4a32babd754'::TEXT, ARRAY[1931]::BIGINT[]),
    (617::BIGINT, 'Es un profe fácil pero uno realmente no aprende en el curso, no explica nada'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '777404bf0e33744d4821c8f7c6374011a1b6c5fc821d2f36a7f0495b337e6279'::TEXT, ARRAY[1927]::BIGINT[]),
    (617::BIGINT, 'La materia es complicada'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f26fa510c8cada8181b028b075360add257105b5df922ff11e77c4a8cfca39fa'::TEXT, ARRAY[1927]::BIGINT[]),
    (617::BIGINT, 'Al mae de abajo se lo sonaron por vago, seguramente. El profesor es una persona muy buena gente, que explica lo justo para que usted sepa hacer las cosas y con base a su experiencia (que es bastante por cierto). Además, puede ser un buen amigo. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c968988967d8784bd2b3fa5b52e9e4c042b8b9be70f2ba36e3b66d70fe7842b6'::TEXT, ARRAY[1927]::BIGINT[]),
    (617::BIGINT, 'Un profesor demasiado aburrido, no se aprende casi nada. Tiene que estudiar solo para que de verdad aprenda e ir mucho a hora consulta. Hace examenes dificiles'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-11-03T00:00:00+00:00'::TIMESTAMPTZ, '547d1bbba479d9977c8197bdd6c596d6a5fb7424405a86a38ea669822fa209ae'::TEXT, ARRAY[1927]::BIGINT[]),
    (617::BIGINT, 'Un hombre con bastante experiencia. Si bien siento que habían aspectos que hacen falta abarcar, el curso fue bastante completo y aunque es estricto para calificar, es muy buena gente y al final la calificación en realidad no es tan dura. Vaya mucho a consulta.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a78b9205db3aa1f1d5b5a9dd6b6cf9847b33fb96c048b437cb52336ab3559da8'::TEXT, ARRAY[1927, 1179]::BIGINT[]),
    (617::BIGINT, 'Es muy buen profesional y tiene bastante experiencia; pero en su clase se aprende si usted decide leer lo que deja y él denota quién se interesa por el curso. Aunque es bastante indiferente y se molesta cuando le preguntan varias veces; es buena gente si va a consulta. (vaya bastante)'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '001c007168ff31f505d014a14f728ccd2b394f408e2d5a26e376bbb4a8465485'::TEXT, ARRAY[1927]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
